package claybin

import (
	"fmt"
	"os"

	"kilnbench/hopsrc/vat"
)

const (
	src       = "/app/vats/plaster.vat"
	dst       = "/app/vats/worker.vat"
	okPath    = "/app/vats/assay.ok"
	migration = "/app/inkstack/migrations"
)

// EmitWorker spills only a fully impressed plaster.  In particular, merely
// having the expected columns is insufficient: its ledger stem must equal the
// current migration head so adding a migration cannot silently create a stale
// worker.
func EmitWorker() error {
	_ = os.Remove(okPath)

	st, err := vat.Parse(src)
	if err != nil {
		return err
	}
	head, err := vat.LedgerHead(migration)
	if err != nil {
		return err
	}
	if st.LastApplied() != head {
		return fmt.Errorf("source schema_version=%s; ledger head=%s", st.LastApplied(), head)
	}
	return vat.CopyFile(src, dst)
}
