package scorepit

import (
	"fmt"
	"os"

	"kilnbench/hopsrc/vat"
)

const (
	worker    = "/app/vats/worker.vat"
	okPath    = "/app/vats/assay.ok"
	migration = "/app/inkstack/migrations"
)

func ScoreWorker() int {
	// A marker from an earlier run must never survive a failed assay.
	_ = os.Remove(okPath)

	st, err := vat.Parse(worker)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}
	version := st.LastApplied()
	fmt.Printf("schema_version=%s\n", version)

	head, err := vat.LedgerHead(migration)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}
	if version != head {
		fmt.Fprintf(os.Stderr, "schema-version mismatch: worker=%s ledger=%s\n", version, head)
		return 1
	}
	if !st.HasCol("attempt_slot") {
		fmt.Fprintln(os.Stderr, "unknown-column: attempt_slot")
		return 1
	}
	if err := os.WriteFile(okPath, []byte("ok\n"), 0644); err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}
	return 0
}
